"use client";

import React, { useState, useEffect } from 'react';
import { motion } from 'motion/react';
import {
  Shield, ShieldAlert, ShieldCheck, AlertTriangle,
  Activity, BarChart3, Clock, Target, ChevronRight,
} from 'lucide-react';
import Link from 'next/link';
import { getScans, ScanRecord } from '../../services/scan-history';

const RISK_CONFIG = {
  Safe:     { color: 'text-[var(--color-safe)]',    bg: 'bg-[var(--color-safe)]/10',    border: 'border-[var(--color-safe)]/30',    bar: 'bg-[var(--color-safe)]' },
  Low:      { color: 'text-blue-400',               bg: 'bg-blue-400/10',               border: 'border-blue-400/30',               bar: 'bg-blue-400' },
  Medium:   { color: 'text-[var(--color-warning)]', bg: 'bg-[var(--color-warning)]/10', border: 'border-[var(--color-warning)]/30', bar: 'bg-[var(--color-warning)]' },
  High:     { color: 'text-orange-500',             bg: 'bg-orange-500/10',             border: 'border-orange-500/30',             bar: 'bg-orange-500' },
  Critical: { color: 'text-[var(--color-danger)]',  bg: 'bg-[var(--color-danger)]/10',  border: 'border-[var(--color-danger)]/30',  bar: 'bg-[var(--color-danger)]' },
} as const;

type RiskLevel = keyof typeof RISK_CONFIG;

export default function DashboardPage() {
  const [scans, setScans] = useState<ScanRecord[]>([]);

  useEffect(() => {
    setScans(getScans());
  }, []);

  const total = scans.length;
  const threats = scans.filter(s => !['Safe', 'Low'].includes(s.result.riskLevel)).length;
  const safe = scans.filter(s => s.result.riskLevel === 'Safe').length;
  const critical = scans.filter(s => s.result.riskLevel === 'Critical').length;
  const avgConfidence = total > 0
    ? Math.round(scans.reduce((acc, s) => acc + s.result.confidenceScore, 0) / total)
    : 0;

  const riskCounts: Record<RiskLevel, number> = {
    Safe:     scans.filter(s => s.result.riskLevel === 'Safe').length,
    Low:      scans.filter(s => s.result.riskLevel === 'Low').length,
    Medium:   scans.filter(s => s.result.riskLevel === 'Medium').length,
    High:     scans.filter(s => s.result.riskLevel === 'High').length,
    Critical: critical,
  };
  const maxRiskCount = Math.max(...Object.values(riskCounts), 1);

  const threatTypeCounts: Record<string, number> = {};
  scans.forEach(s => {
    const t = s.result.threatType || 'Unknown';
    threatTypeCounts[t] = (threatTypeCounts[t] || 0) + 1;
  });
  const topThreatTypes = Object.entries(threatTypeCounts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5);

  const recent = scans.slice(0, 6);

  const statCards = [
    { label: 'Total Scans',       value: total,            icon: BarChart3,    color: 'text-[var(--color-primary)]', bg: 'bg-[var(--color-primary)]/10' },
    { label: 'Threats Detected',  value: threats,          icon: ShieldAlert,  color: 'text-orange-500',             bg: 'bg-orange-500/10' },
    { label: 'Safe Results',      value: safe,             icon: ShieldCheck,  color: 'text-[var(--color-safe)]',    bg: 'bg-[var(--color-safe)]/10' },
    { label: 'Avg Confidence',    value: `${avgConfidence}%`, icon: Target,    color: 'text-indigo-400',             bg: 'bg-indigo-400/10' },
  ];

  return (
    <main className="flex-1 flex flex-col h-full overflow-hidden relative">
      <div className="flex-1 overflow-y-auto p-4 md:p-8 lg:p-10">
        <div className="max-w-6xl mx-auto space-y-8">

          {/* Header */}
          <header className="space-y-1">
            <h2 className="text-3xl font-bold text-white tracking-tight">Dashboard</h2>
            <p className="text-slate-400">Overview of your threat analysis activity and intelligence.</p>
          </header>

          {/* Stat Cards */}
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
            {statCards.map((card, i) => (
              <motion.div
                key={card.label}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.08 }}
                className="glass-panel rounded-2xl p-6"
              >
                <div className={`w-10 h-10 rounded-xl ${card.bg} flex items-center justify-center mb-4`}>
                  <card.icon className={`w-5 h-5 ${card.color}`} />
                </div>
                <p className="text-3xl font-bold text-white">{card.value}</p>
                <p className="text-sm text-slate-400 mt-1">{card.label}</p>
              </motion.div>
            ))}
          </div>

          {/* Risk Distribution + Top Threats */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

            {/* Risk Distribution */}
            <div className="glass-panel rounded-2xl p-6">
              <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider flex items-center gap-2 mb-6">
                <BarChart3 className="w-4 h-4 text-[var(--color-primary)]" />
                Risk Level Distribution
              </h3>
              {total === 0 ? (
                <div className="flex flex-col items-center justify-center h-40 text-slate-500">
                  <Shield className="w-10 h-10 mb-3 opacity-30" />
                  <p className="text-sm">No scans yet</p>
                </div>
              ) : (
                <div className="space-y-4">
                  {(Object.keys(riskCounts) as RiskLevel[]).map(level => (
                    <div key={level} className="space-y-1.5">
                      <div className="flex justify-between items-center text-sm">
                        <span className={`font-medium ${RISK_CONFIG[level].color}`}>{level}</span>
                        <span className="text-slate-400 tabular-nums">{riskCounts[level]}</span>
                      </div>
                      <div className="h-2 bg-white/5 rounded-full overflow-hidden">
                        <motion.div
                          initial={{ width: 0 }}
                          animate={{ width: `${(riskCounts[level] / maxRiskCount) * 100}%` }}
                          transition={{ duration: 0.8, ease: 'easeOut' }}
                          className={`h-full ${RISK_CONFIG[level].bar} rounded-full`}
                        />
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Top Threat Types */}
            <div className="glass-panel rounded-2xl p-6">
              <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider flex items-center gap-2 mb-6">
                <Target className="w-4 h-4 text-[var(--color-primary)]" />
                Top Threat Categories
              </h3>
              {topThreatTypes.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-40 text-slate-500">
                  <Shield className="w-10 h-10 mb-3 opacity-30" />
                  <p className="text-sm">No data yet</p>
                </div>
              ) : (
                <div className="space-y-3">
                  {topThreatTypes.map(([type, count], i) => (
                    <div key={type} className="flex items-center gap-3">
                      <span className="w-6 h-6 rounded-full bg-[var(--color-primary)]/10 text-[var(--color-primary)] flex items-center justify-center text-xs font-bold border border-[var(--color-primary)]/20 shrink-0">
                        {i + 1}
                      </span>
                      <span className="flex-1 text-sm text-slate-300 truncate">{type}</span>
                      <span className="text-xs font-semibold text-[var(--color-primary)] bg-[var(--color-primary)]/10 px-2 py-1 rounded-full tabular-nums">
                        {count}×
                      </span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Recent Activity */}
          <div className="glass-panel rounded-2xl p-6">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                <Clock className="w-4 h-4 text-[var(--color-primary)]" />
                Recent Activity
              </h3>
              <Link href="/reports" className="text-xs text-[var(--color-primary)] hover:underline flex items-center gap-0.5">
                View all <ChevronRight className="w-3 h-3" />
              </Link>
            </div>

            {recent.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-40 text-slate-500">
                <Activity className="w-10 h-10 mb-3 opacity-30" />
                <p className="text-sm">No scans yet.</p>
                <Link href="/" className="mt-3 text-xs text-[var(--color-primary)] hover:underline">
                  Run a scan →
                </Link>
              </div>
            ) : (
              <div className="space-y-1">
                {recent.map((scan, i) => {
                  const cfg = RISK_CONFIG[scan.result.riskLevel as RiskLevel];
                  return (
                    <motion.div
                      key={scan.id}
                      initial={{ opacity: 0, x: -10 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: i * 0.06 }}
                      className="flex items-center gap-4 p-3 rounded-xl hover:bg-white/5 transition-colors"
                    >
                      <div className={`w-2 h-2 rounded-full ${cfg.bar} shrink-0`} />
                      <div className="flex-1 min-w-0">
                        <p className="text-sm text-slate-300 truncate">{scan.input}</p>
                        <p className="text-xs text-slate-500 mt-0.5">
                          {scan.result.threatType} · {new Date(scan.timestamp).toLocaleDateString()}
                        </p>
                      </div>
                      <span className={`text-xs font-semibold px-2.5 py-1 rounded-full border shrink-0 ${cfg.bg} ${cfg.color} ${cfg.border}`}>
                        {scan.result.riskLevel}
                      </span>
                    </motion.div>
                  );
                })}
              </div>
            )}
          </div>

          {/* Critical Alert Banner */}
          {critical > 0 && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="p-4 rounded-xl bg-red-500/10 border border-red-500/30 flex items-start gap-3"
            >
              <AlertTriangle className="w-5 h-5 text-red-400 shrink-0 mt-0.5" />
              <div className="flex-1">
                <p className="text-red-300 font-semibold text-sm">Critical Threats Detected</p>
                <p className="text-red-400/80 text-xs mt-0.5">
                  {critical} critical threat{critical > 1 ? 's' : ''} found in scan history. Review the Reports page immediately.
                </p>
              </div>
              <Link href="/reports" className="text-xs text-red-400 hover:text-red-300 flex items-center gap-1 shrink-0">
                Review <ChevronRight className="w-3 h-3" />
              </Link>
            </motion.div>
          )}

        </div>
      </div>

      {/* Background glows */}
      <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] rounded-full bg-[var(--color-primary)]/5 blur-[120px] pointer-events-none" />
      <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] rounded-full bg-[var(--color-accent)]/5 blur-[120px] pointer-events-none" />
    </main>
  );
}
